//! Jarvis small-talk / FAQ bank (ADR-0049): 100+ intents with 15 000+
//! Russian question phrasings (`data/dialog.json`, generated by
//! `scripts/gen-jarvis-dialog.mjs`) answered locally — no tokens.
//!
//! Matching reuses the command matcher's text layer ([`tokenize`]:
//! normalization, light Russian stemming, concepts, fillers; [`token_cost`]:
//! fuzzy tokens) after a dialog normalization (`оркестр` stays a word,
//! openers such as «слушай», «ну», «а» are dropped), but scores differently
//! from the command aligner: small talk is order-free and its frames
//! («хочу спросить», «кстати», «если честно») say little, so tokens are
//! weighted by inverse intent frequency and the score is a weighted Dice
//! coefficient between the utterance and the best phrasing. Unknown words in
//! the utterance weigh the most — a real question («кто такой Илон Маск»)
//! falls through to the AI. Answers rotate variants without repeating the last one and
//! fill runtime slots: `{address}` / `{Address}` (form of address), `{time}`,
//! `{date}`, `{date_full}`, `{weekday}`, `{tomorrow}`, `{yesterday}`,
//! `{month}`, `{year}`, `{days_to_ny}`, `{weekend}`, `{greeting}`, `{coin}`,
//! `{dice}`, `{number}`, `{last}`.

use std::collections::HashMap;
use std::sync::OnceLock;

use chrono::{Datelike, NaiveDate, NaiveDateTime, Timelike, Weekday};
use orkestr_protocol::methods::jarvis::{JarvisAddress, JarvisBankStats};
use parking_lot::Mutex;
use serde::Deserialize;

use crate::text::{token_cost, tokenize, Token};

/// Minimum score of a small-talk match (stricter than commands: a miss
/// costs an AI answer, a false hit answers the wrong question).
pub const DIALOG_THRESHOLD: f32 = 0.7;

/// Openers / address words that never carry a small-talk intent (in
/// addition to the matcher's fillers); mirrored in the generator.
const DIALOG_FILLERS: &[&str] = &[
    "джарвиса",
    "джарвису",
    "джарвисом",
    "джарвисик",
    "ну",
    "же",
    "слушай",
    "скажи",
    "подскажи",
    "а",
    "о",
    "ох",
    "ой",
    "знаешь",
    "отныне",
    "теперь",
    "бро",
    "дружище",
    "старина",
    "приятель",
    "братан",
];

const BUILTIN: &str = include_str!("../data/dialog.json");

#[derive(Debug, Deserialize)]
struct BankFile {
    intents: Vec<IntentFile>,
}

#[derive(Debug, Deserialize)]
struct IntentFile {
    id: String,
    category: String,
    questions: Vec<String>,
    answers: Vec<String>,
    #[serde(default)]
    action: Option<String>,
}

/// One intent of the bank.
#[derive(Debug, Clone)]
pub struct DialogIntent {
    /// Intent id.
    pub id: String,
    /// Category.
    pub category: String,
    /// Answer templates.
    pub answers: Vec<String>,
    /// Client action.
    pub action: Option<String>,
    /// Number of question phrasings.
    pub questions: usize,
}

/// A small-talk match.
#[derive(Debug, Clone, PartialEq)]
pub struct DialogMatch {
    /// Intent index.
    pub index: usize,
    /// Intent id.
    pub intent: String,
    /// Score 0..1.
    pub score: f32,
    /// Phrase that matched.
    pub phrase: String,
}

/// Runtime values of the answer slots.
#[derive(Debug, Clone)]
pub struct RenderContext {
    /// Form of address.
    pub address: JarvisAddress,
    /// User name (for [`JarvisAddress::Name`]).
    pub user_name: String,
    /// Persona on (off: no address).
    pub persona: bool,
    /// Local time.
    pub now: NaiveDateTime,
    /// What Jarvis said last (`{last}`).
    pub last_reply: Option<String>,
    /// Random seed (variants, coin, dice).
    pub seed: u64,
}

/// The template bank.
pub struct DialogBank {
    intents: Vec<DialogIntent>,
    index: Index,
    last: Mutex<HashMap<usize, usize>>,
}

/// One compiled phrasing.
#[derive(Debug)]
struct Phrase {
    intent: usize,
    text: String,
    keys: Vec<u32>,
    weight: f32,
}

/// Weighted inverted index over the phrasings.
#[derive(Debug, Default)]
struct Index {
    keys: Vec<String>,
    key_of: HashMap<String, u32>,
    weight: Vec<f32>,
    postings: Vec<Vec<u32>>,
    phrases: Vec<Phrase>,
    max_weight: f32,
}

impl Index {
    fn build(questions: &[(usize, String)], intents: usize) -> Self {
        let mut ix = Index::default();
        let mut df: Vec<Vec<usize>> = Vec::new();
        for (intent, q) in questions {
            let toks = tokenize(&normalize(q));
            if toks.is_empty() {
                continue;
            }
            let mut keys = Vec::with_capacity(toks.len());
            for t in toks {
                let id = if let Some(&id) = ix.key_of.get(&t.key) {
                    id
                } else {
                    let id = u32::try_from(ix.keys.len()).unwrap_or(u32::MAX);
                    ix.key_of.insert(t.key.clone(), id);
                    ix.keys.push(t.key);
                    ix.postings.push(Vec::new());
                    df.push(Vec::new());
                    id
                };
                let d = &mut df[id as usize];
                if !d.contains(intent) {
                    d.push(*intent);
                }
                keys.push(id);
            }
            let pid = u32::try_from(ix.phrases.len()).unwrap_or(u32::MAX);
            for &k in &keys {
                let p = &mut ix.postings[k as usize];
                if p.last() != Some(&pid) {
                    p.push(pid);
                }
            }
            ix.phrases.push(Phrase { intent: *intent, text: q.clone(), keys, weight: 0.0 });
        }
        #[allow(clippy::cast_precision_loss)]
        let n = intents.max(1) as f32;
        #[allow(clippy::cast_precision_loss)]
        let idf = |d: usize| (1.0 + n / d.max(1) as f32).ln().max(0.15);
        ix.weight = df.iter().map(|d| idf(d.len())).collect();
        ix.max_weight = idf(1);
        for p in &mut ix.phrases {
            p.weight = p.keys.iter().map(|&k| ix.weight[k as usize]).sum();
        }
        ix
    }

    /// Vocabulary hits of one utterance token: `(key, cost)`.
    fn hits(&self, t: &Token) -> Vec<(u32, f32)> {
        if let Some(&id) = self.key_of.get(&t.key).or_else(|| self.key_of.get(&t.word)) {
            return vec![(id, 0.0)];
        }
        let mut out = Vec::new();
        for (id, k) in self.keys.iter().enumerate() {
            // prefix / fuzzy matches only between words of similar length
            // («марк» must not take «маркет»)
            if k.chars().count().abs_diff(t.key.chars().count()) > 2 {
                continue;
            }
            if let Some(c) = token_cost(k, t) {
                out.push((u32::try_from(id).unwrap_or(u32::MAX), c));
            }
        }
        out
    }

    /// Best phrasing: `(phrase, score)`.
    fn best(&self, text: &str) -> Option<(usize, f32)> {
        let toks = tokenize(text);
        if toks.is_empty() || toks.len() > 40 {
            return None;
        }
        let hits: Vec<Vec<(u32, f32)>> = toks.iter().map(|t| self.hits(t)).collect();
        // an utterance token weighs as its best vocabulary word; unknown words weigh the most
        let w_in: Vec<f32> = hits
            .iter()
            .map(|h| {
                h.iter().min_by(|a, b| a.1.total_cmp(&b.1)).map_or(self.max_weight, |&(k, _)| self.weight[k as usize])
            })
            .collect();
        let total_in: f32 = w_in.iter().sum();
        let mut seen = vec![false; self.phrases.len()];
        let mut used = vec![false; toks.len()];
        let mut best: Option<(usize, f32)> = None;
        for h in &hits {
            for &(k, _) in h {
                for &pid in &self.postings[k as usize] {
                    let pid = pid as usize;
                    if std::mem::replace(&mut seen[pid], true) {
                        continue;
                    }
                    let p = &self.phrases[pid];
                    used.iter_mut().for_each(|u| *u = false);
                    let mut matched = 0.0_f32;
                    for &pk in &p.keys {
                        let mut pick: Option<(usize, f32)> = None;
                        for (i, hi) in hits.iter().enumerate() {
                            if used[i] {
                                continue;
                            }
                            if let Some(&(_, c)) = hi.iter().find(|(kk, _)| *kk == pk) {
                                let v = w_in[i].min(self.weight[pk as usize]) * (1.0 - c);
                                if pick.is_none_or(|(_, bv)| v > bv) {
                                    pick = Some((i, v));
                                }
                            }
                        }
                        if let Some((i, v)) = pick {
                            used[i] = true;
                            matched += v;
                        }
                    }
                    let score = 2.0 * matched / (p.weight + total_in);
                    let better = match best {
                        None => true,
                        Some((bp, bs)) => score > bs || (score == bs && p.keys.len() < self.phrases[bp].keys.len()),
                    };
                    if better {
                        best = Some((pid, score));
                    }
                }
            }
        }
        best
    }
}

impl std::fmt::Debug for DialogBank {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("DialogBank").field("intents", &self.intents.len()).finish_non_exhaustive()
    }
}

/// Dialog normalization before tokenizing: keeps «оркестр» as a word (the
/// command matcher treats it as a filler) and drops address / interjections.
#[must_use]
pub fn normalize(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for raw in text.split(|c: char| c.is_whitespace() || (c.is_ascii_punctuation() && c != '+' && c != '\'')) {
        let w = raw.trim_matches(|c: char| !c.is_alphanumeric());
        if w.is_empty() {
            continue;
        }
        let lower = w.to_lowercase().replace('ё', "е");
        let word = match lower.as_str() {
            "оркестр" | "оркестра" | "оркестре" | "оркестром" | "оркестру" | "orkestr" => {
                "orkapp"
            }
            w if DIALOG_FILLERS.contains(&w) => continue,
            _ => w,
        };
        if !out.is_empty() {
            out.push(' ');
        }
        out.push_str(word);
    }
    out
}

impl DialogBank {
    /// The built-in bank (parsed once).
    ///
    /// # Panics
    /// Only if the bundled `data/dialog.json` is invalid (a test guards it).
    pub fn builtin() -> &'static DialogBank {
        static BANK: OnceLock<DialogBank> = OnceLock::new();
        BANK.get_or_init(|| DialogBank::from_json(BUILTIN).expect("bundled dialog bank is valid"))
    }

    /// Parses a bank file.
    ///
    /// # Errors
    /// Invalid JSON or an intent without answers.
    pub fn from_json(json: &str) -> Result<Self, String> {
        let file: BankFile = serde_json::from_str(json).map_err(|e| format!("dialog bank: {e}"))?;
        let mut intents = Vec::with_capacity(file.intents.len());
        let mut questions = Vec::new();
        for (n, i) in file.intents.into_iter().enumerate() {
            if i.answers.is_empty() {
                return Err(format!("dialog intent {} has no answers", i.id));
            }
            questions.extend(i.questions.iter().map(|q| (n, q.clone())));
            intents.push(DialogIntent {
                id: i.id,
                category: i.category,
                answers: i.answers,
                action: i.action,
                questions: i.questions.len(),
            });
        }
        let index = Index::build(&questions, intents.len());
        Ok(Self { intents, index, last: Mutex::new(HashMap::new()) })
    }

    /// Intents.
    #[must_use]
    pub fn intents(&self) -> &[DialogIntent] {
        &self.intents
    }

    /// Bank size.
    #[must_use]
    pub fn stats(&self) -> JarvisBankStats {
        let n = |v: usize| u32::try_from(v).unwrap_or(u32::MAX);
        JarvisBankStats {
            intents: n(self.intents.len()),
            questions: n(self.intents.iter().map(|i| i.questions).sum()),
            answers: n(self.intents.iter().map(|i| i.answers.len()).sum()),
        }
    }

    /// Best intent for `text` at or above `min_score`.
    #[must_use]
    pub fn find_with(&self, text: &str, min_score: f32) -> Option<DialogMatch> {
        let norm = normalize(text);
        if norm.is_empty() || norm.chars().count() > 300 {
            return None;
        }
        let (pid, score) = self.index.best(&norm)?;
        if score < min_score {
            return None;
        }
        let p = &self.index.phrases[pid];
        Some(DialogMatch { index: p.intent, intent: self.intents[p.intent].id.clone(), score, phrase: p.text.clone() })
    }

    /// Best intent for `text` (≥ [`DIALOG_THRESHOLD`]).
    #[must_use]
    pub fn find(&self, text: &str) -> Option<DialogMatch> {
        self.find_with(text, DIALOG_THRESHOLD)
    }

    /// The intent of a match.
    #[must_use]
    pub fn intent(&self, m: &DialogMatch) -> &DialogIntent {
        &self.intents[m.index]
    }

    /// Renders an answer: a variant other than the last one of this intent.
    #[must_use]
    pub fn answer(&self, m: &DialogMatch, ctx: &RenderContext) -> String {
        let intent = &self.intents[m.index];
        let n = intent.answers.len();
        let pick = {
            let mut last = self.last.lock();
            let prev = last.get(&m.index).copied();
            let mut k = usize::try_from(ctx.seed % n as u64).unwrap_or(0);
            if n > 1 && Some(k) == prev {
                k = (k + 1 + usize::try_from((ctx.seed >> 16) % (n as u64 - 1)).unwrap_or(0)) % n;
                if Some(k) == prev {
                    k = (k + 1) % n;
                }
            }
            last.insert(m.index, k);
            k
        };
        render(&intent.answers[pick], ctx)
    }
}

const MONTHS_GEN: [&str; 12] = [
    "января",
    "февраля",
    "марта",
    "апреля",
    "мая",
    "июня",
    "июля",
    "августа",
    "сентября",
    "октября",
    "ноября",
    "декабря",
];
const MONTHS_NOM: [&str; 12] = [
    "январь",
    "февраль",
    "март",
    "апрель",
    "май",
    "июнь",
    "июль",
    "август",
    "сентябрь",
    "октябрь",
    "ноябрь",
    "декабрь",
];

fn weekday_ru(w: Weekday) -> &'static str {
    match w {
        Weekday::Mon => "понедельник",
        Weekday::Tue => "вторник",
        Weekday::Wed => "среда",
        Weekday::Thu => "четверг",
        Weekday::Fri => "пятница",
        Weekday::Sat => "суббота",
        Weekday::Sun => "воскресенье",
    }
}

/// Russian plural form (`1 день`, `2 дня`, `5 дней`).
#[must_use]
pub fn plural_ru(n: i64, one: &str, few: &str, many: &str) -> String {
    let m10 = n.rem_euclid(10);
    let m100 = n.rem_euclid(100);
    let w = if m10 == 1 && m100 != 11 {
        one
    } else if (2..=4).contains(&m10) && !(12..=14).contains(&m100) {
        few
    } else {
        many
    };
    format!("{n} {w}")
}

fn day_month(d: NaiveDate) -> String {
    format!("{} {}", d.day(), MONTHS_GEN[d.month0() as usize])
}

/// Time-of-day greeting.
#[must_use]
pub fn greeting_ru(hour: u32) -> &'static str {
    match hour {
        5..=11 => "Доброе утро",
        12..=17 => "Добрый день",
        18..=22 => "Добрый вечер",
        _ => "Доброй ночи",
    }
}

fn weekend_ru(d: NaiveDate) -> String {
    match d.weekday() {
        Weekday::Sat => "Выходные уже наступили".into(),
        Weekday::Sun => "Сегодня ещё выходной".into(),
        Weekday::Fri => "Выходные начинаются завтра".into(),
        w => {
            let left = 5 - i64::from(w.num_days_from_monday());
            format!("До выходных {}", plural_ru(left, "день", "дня", "дней"))
        }
    }
}

fn upper_first(s: &str) -> String {
    let mut c = s.chars();
    c.next().map_or_else(String::new, |f| f.to_uppercase().collect::<String>() + c.as_str())
}

/// Address in suffix (`, сэр`) and prefix (`Сэр, `) form.
#[must_use]
pub fn address_forms(address: JarvisAddress, user_name: &str, persona: bool) -> (String, String) {
    let word = match address {
        _ if !persona => return (String::new(), String::new()),
        JarvisAddress::Sir => "сэр".to_owned(),
        JarvisAddress::Boss => "босс".to_owned(),
        JarvisAddress::Name if !user_name.trim().is_empty() => user_name.trim().to_owned(),
        JarvisAddress::Name | JarvisAddress::None => return (String::new(), String::new()),
    };
    (format!(", {word}"), format!("{}, ", upper_first(&word)))
}

/// Fills the slots of an answer template.
#[must_use]
pub fn render(template: &str, ctx: &RenderContext) -> String {
    let (suffix, prefix) = address_forms(ctx.address, &ctx.user_name, ctx.persona);
    let now = ctx.now;
    let today = now.date();
    let tomorrow = today.succ_opt().unwrap_or(today);
    let yesterday = today.pred_opt().unwrap_or(today);
    let ny = NaiveDate::from_ymd_opt(today.year() + 1, 1, 1).unwrap_or(today);
    let days_to_ny = (ny - today).num_days();
    let mut out = template.to_owned();
    let slots: [(&str, String); 16] = [
        ("{address}", suffix),
        ("{time}", format!("{}:{:02}", now.hour(), now.minute())),
        ("{date_full}", format!("{}, {} {} года", weekday_ru(today.weekday()), day_month(today), today.year())),
        ("{date}", day_month(today)),
        ("{weekday}", weekday_ru(today.weekday()).to_owned()),
        ("{tomorrow}", format!("{}, {}", weekday_ru(tomorrow.weekday()), day_month(tomorrow))),
        ("{yesterday}", format!("{}, {}", weekday_ru(yesterday.weekday()), day_month(yesterday))),
        ("{month}", MONTHS_NOM[today.month0() as usize].to_owned()),
        ("{year}", today.year().to_string()),
        ("{days_to_ny}", plural_ru(days_to_ny, "день", "дня", "дней")),
        ("{weekend}", weekend_ru(today)),
        ("{greeting}", greeting_ru(now.hour()).to_owned()),
        ("{coin}", if ctx.seed >> 7 & 1 == 0 { "Орёл".to_owned() } else { "Решка".to_owned() }),
        ("{dice}", ((ctx.seed >> 9) % 6 + 1).to_string()),
        ("{number}", ((ctx.seed >> 13) % 100 + 1).to_string()),
        (
            "{last}",
            ctx.last_reply
                .clone()
                .filter(|s| !s.trim().is_empty())
                .unwrap_or_else(|| "я пока ничего не говорил.".into()),
        ),
    ];
    for (k, v) in &slots {
        if out.contains(k) {
            out = out.replace(k, v);
        }
    }
    if out.contains("{Address}") {
        if prefix.is_empty() {
            // «{Address}боюсь…» without an address: capitalize what follows
            let idx = out.find("{Address}").unwrap_or(0);
            let (head, tail) = out.split_at(idx);
            let rest = &tail["{Address}".len()..];
            out = format!("{head}{}", if head.trim().is_empty() { upper_first(rest) } else { rest.to_owned() });
        } else {
            out = out.replace("{Address}", &prefix);
        }
    }
    // an address before a sentence end that already starts lower-case (", сэр. {last}") stays as is
    if out.starts_with(|c: char| c.is_lowercase()) {
        out = upper_first(&out);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn ctx(address: JarvisAddress) -> RenderContext {
        RenderContext {
            address,
            user_name: "Фаррух".into(),
            persona: true,
            now: NaiveDate::from_ymd_opt(2026, 10, 26).unwrap().and_hms_opt(9, 5, 0).unwrap(),
            last_reply: None,
            seed: 0,
        }
    }

    #[test]
    fn address_forms_by_setting() {
        assert_eq!(address_forms(JarvisAddress::Sir, "", true).0, ", сэр");
        assert_eq!(address_forms(JarvisAddress::Boss, "", true).1, "Босс, ");
        assert_eq!(address_forms(JarvisAddress::Name, "Фаррух", true).0, ", Фаррух");
        assert_eq!(address_forms(JarvisAddress::Name, " ", true).0, "");
        assert_eq!(address_forms(JarvisAddress::Sir, "", false).0, "");
    }

    #[test]
    fn slots_render() {
        let c = ctx(JarvisAddress::Sir);
        assert_eq!(render("Сейчас {time}{address}.", &c), "Сейчас 9:05, сэр.");
        assert_eq!(render("Сегодня {date_full}{address}.", &c), "Сегодня понедельник, 26 октября 2026 года, сэр.");
        assert_eq!(render("Завтра {tomorrow}.", &c), "Завтра вторник, 27 октября.");
        assert_eq!(render("{greeting}{address}.", &c), "Доброе утро, сэр.");
        assert_eq!(render("До Нового года {days_to_ny}.", &c), "До Нового года 67 дней.");
        assert_eq!(render("{weekend}.", &c), "До выходных 5 дней.");
        assert_eq!(render("{Address}боюсь, нет.", &c), "Сэр, боюсь, нет.");
        assert_eq!(render("{Address}боюсь, нет.", &ctx(JarvisAddress::None)), "Боюсь, нет.");
        assert_eq!(render("Готово{address}.", &ctx(JarvisAddress::Name)), "Готово, Фаррух.");
    }

    #[test]
    fn plurals() {
        assert_eq!(plural_ru(1, "день", "дня", "дней"), "1 день");
        assert_eq!(plural_ru(22, "день", "дня", "дней"), "22 дня");
        assert_eq!(plural_ru(11, "день", "дня", "дней"), "11 дней");
        assert_eq!(plural_ru(105, "день", "дня", "дней"), "105 дней");
    }

    #[test]
    fn dialog_normalization() {
        assert_eq!(normalize("Ну, что такое Оркестр?"), "что такое orkapp");
        assert_eq!(normalize("Привет, Джарвиса!"), "Привет");
    }

    #[test]
    fn answers_rotate_without_repeats() {
        let bank = DialogBank::from_json(
            r#"{"intents":[{"id":"x","category":"c","questions":["как дела"],"answers":["a{address}","b{address}","c{address}"]}]}"#,
        )
        .unwrap();
        let m = bank.find("как дела").unwrap();
        let mut prev = String::new();
        for seed in [0_u64, 0, 0, 3, 3, 6, 6, 1, 1] {
            let a = bank.answer(&m, &RenderContext { seed, ..ctx(JarvisAddress::Sir) });
            assert_ne!(a, prev, "no immediate repeat");
            prev = a;
        }
    }
}
